const $=s=>document.querySelector(s);let current=localStorage.getItem('dcv_current_project')||null,token=sessionStorage.getItem('dcv_token')||'',projects=[],candidates=[],currentGateSnapshot=null,currentResearchCycle=1;
const stageOrder=['define','measure','compute','validate','recompute','approved','report'];
const stageAlias={scientific_review:'approved',complete:'report',report_ready:'report'};
const stageIdx=s=>Math.max(0,stageOrder.indexOf(stageAlias[s]||s));
const stageInfo=[['Define','연구 범위 정의','bi-diagram-3'],['Measure','지표 측정·수집','bi-database'],['Compute','CDRS 계산·경계탐색','bi-cpu'],['Validate','강건 검증','bi-shield-check'],['Recompute','인간 보정 재계산','bi-arrow-repeat'],['Approve','최종 승인','bi-person-check']];
async function api(path,opts={}){const h={'content-type':'application/json','cache-control':'no-cache',...(opts.headers||{})};if(token)h.authorization=`Bearer ${token}`;const r=await fetch(path,{cache:'no-store',...opts,headers:h});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||r.statusText);return j;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>Number(v||0).toLocaleString('ko-KR',{maximumFractionDigits:d});
const fmtTs=v=>{if(!v)return '-';try{return new Date(v).toLocaleString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}catch{return String(v)}};
function participantStorageKey(projectId=current,cycle=currentResearchCycle){return `dcv_participant:${projectId||'none'}:${Number(cycle||1)}`;}
function ensureParticipantSession(){if(!current)return null;const key=participantStorageKey(),legacy=localStorage.getItem('dcv_participant');let ph=localStorage.getItem(key);if(!ph&&legacy){ph=legacy;localStorage.setItem(key,ph);}if(!ph){ph=crypto.randomUUID();localStorage.setItem(key,ph);}return ph;}
function participantShort(ph){return ph?`P-${String(ph).replace(/-/g,'').slice(0,8).toUpperCase()}`:'미지정';}
function updateParticipantSessionUI(d=null){const ph=ensureParticipantSession(),badge=$('#participantSession'),info=$('#participantCountInfo');if(badge)badge.textContent=participantShort(ph);if(info&&d)info.textContent=`현재 분석 ${num(d.human_eligible_participants||0)}명 · 누적 ${num(d.human_participants||0)}명`;}
function modal(id){return bootstrap.Modal.getOrCreateInstance(document.getElementById(id));}
function workflow(stage='define'){const cur=stageIdx(stage);$('#workflowRibbon').innerHTML=stageInfo.map((x,i)=>`<div class="workflow-step ${i<cur?'done':''} ${i===cur?'active':''} ${i===5?'approve':''}"><span class="step-icon"><i class="bi ${x[2]}"></i></span><div><b>0${i+1} ${x[0]}</b><small>${x[1]}</small></div></div>`).join('');}
function metric(icon,label,value,sub,delta=''){return `<div class="col-6 col-lg-3"><article class="metric-card"><div class="metric-head"><span>${esc(label)}</span><i class="bi ${icon}"></i></div><div class="metric-value">${value}</div><div class="metric-sub">${sub}</div>${delta?`<div class="metric-delta mt-2">${delta}</div>`:''}</article></div>`;}
function storageBanner(msg,kind='danger'){let b=document.getElementById('storageSafetyBanner');if(!b){b=document.createElement('div');b.id='storageSafetyBanner';b.className='container-fluid px-4 pt-3';const host=document.querySelector('main')||document.body;host.prepend(b);}b.innerHTML=msg?`<div class="alert alert-${kind} mb-0"><b>저장소 안전 점검</b><br>${esc(msg)}</div>`:'';}
function renderResearchBrief(d=null,state='ready'){const el=document.getElementById('currentResearchBrief');if(!el)return;if(!d){const last=current?`마지막 프로젝트 ID ${current}`:'등록 프로젝트 없음';el.classList.toggle('briefing-warning',state==='error');el.innerHTML=`<div class="briefing-heading"><span>RESEARCH BRIEFING</span><b>${state==='error'?'연구 데이터를 불러오지 못했습니다.':'현재 연결된 연구 프로젝트가 없습니다.'}</b><small>${state==='error'?'기존 데이터를 새 프로젝트로 대체하지 마세요. 저장소 연결을 확인한 뒤 복구를 다시 시도합니다.':`${last} · 새 연구를 만들기 전에 D1 저장소가 맞는지 확인하세요.`}</small></div><div class="briefing-facts"><div><span>CURRENT STAGE</span><b>—</b></div><div><span>CANDIDATES</span><b>—</b></div><div><span>EVIDENCE</span><b>—</b></div><div><span>APPROVAL</span><b>—</b></div></div>`;return;}const p=d.project||{},c=d.candidates||{},ag=d.approval_gates||{};const stage=String(p.current_stage||'define').toUpperCase();const cand=Number(c.total||p.candidate_count||0);const rev=Number(p.evidence_revision||ag.evidence_revision||0);const passed=Number(ag.passed||0),total=Number(ag.total||6);el.classList.remove('briefing-warning');el.innerHTML=`<div class="briefing-heading"><span>RESEARCH BRIEFING</span><b>${esc(p.name||'DCV 연구 프로젝트')}</b><small>${esc(p.description||'현재 프로젝트의 연구상태와 검증 진행도를 실시간으로 표시합니다.')} · HYBRID FAST: Worker 상태전환 / GitHub 중량계산</small></div><div class="briefing-facts"><div><span>CURRENT STAGE</span><b>${esc(stage)}</b></div><div><span>CANDIDATES</span><b>${num(cand)}</b></div><div><span>EVIDENCE</span><b>r${num(rev)}</b></div><div><span>APPROVAL</span><b>${num(passed)}/${num(total)}</b></div></div>`;}
async function recoverLastProject(){if(!current)return null;try{const d=await api(`/api/projects/${current}`);if(!d?.project)return null;const p={...d.project,candidate_count:Number(d.candidates?.total||0),approval_count:d.approval?1:0};projects=[p];renderProjects();localStorage.setItem('dcv_project_count','1');storageBanner('프로젝트 목록 조회 결과에는 없었지만 마지막으로 열었던 프로젝트를 직접 조회해 복구했습니다. D1 목록/스키마 호환 상태를 점검하세요.','warning');return p;}catch(e){console.warn('last project recovery failed',e);return null;}}
async function load(){try{const d=await api('/api/projects');projects=d.projects||[];const integ=d.integrity||{};const oldLineage=localStorage.getItem('dcv_storage_lineage'),oldCount=Number(localStorage.getItem('dcv_project_count')||0);if(oldLineage&&integ.storage_lineage_id&&oldLineage!==integ.storage_lineage_id){storageBanner(`이 브라우저에서 마지막으로 사용한 D1 저장소와 현재 저장소가 다릅니다. 기존 프로젝트가 삭제된 것으로 단정하지 마세요. wrangler.jsonc의 database_id/DB binding을 먼저 확인해야 합니다. 이전 프로젝트 ${oldCount}개, 현재 ${Number(integ.project_count||0)}개.`);}else if(oldCount>0&&Number(integ.project_count||0)===0){storageBanner(`이전에 ${oldCount}개 프로젝트를 확인했지만 현재 연결된 D1에서는 0개입니다. 배포·migration·D1 binding을 확인하세요. 플랫폼은 자동으로 새 프로젝트를 만들거나 기존 프로젝트를 삭제하지 않습니다.`);}else storageBanner('');if(integ.storage_lineage_id)localStorage.setItem('dcv_storage_lineage',integ.storage_lineage_id);localStorage.setItem('dcv_project_count',String(projects.length));renderProjects();const approved=projects.filter(p=>p.approval_count>0).length,totalCand=projects.reduce((a,p)=>a+Number(p.candidate_count||0),0);$('#stats').innerHTML=metric('bi-layers','연구 프로젝트',num(projects.length),'등록된 DCV 연구',`${projects.filter(p=>p.status!=='complete').length}개 진행 중`)+metric('bi-cpu','설계 후보',num(totalCand),'CDRS 탐색 후보','경계 집중 탐색')+metric('bi-shield-check','승인 완료',num(approved),'검증·보정 통과','Evidence based')+metric('bi-stars','연구 파이프라인',projects.length?'HYBRID FAST':'READY','Worker orchestration + GitHub compute','Define → Approve');let preferred=projects.find(p=>p.id===current)||projects[0];if(!preferred&&current)preferred=await recoverLastProject();if(preferred){document.body.classList.remove('no-project');await openProject(preferred.id);}else{workflow();renderEmpty();renderResearchBrief(null,'ready');}return true;}catch(e){if(String(e).includes('unauthorized'))modal('tokenModal').show();else{console.error(e);document.body.classList.add('no-project');renderResearchBrief(null,'error');storageBanner(`프로젝트 조회에 실패했습니다: ${e.message}. 빈 목록을 데이터 삭제로 해석하지 마세요. 원격 D1 migration 및 DB binding 상태를 확인하세요.`);}return false;}}
function renderProjects(filter=''){const q=filter.trim().toLowerCase();const xs=projects.filter(p=>(p.name+' '+p.status+' '+p.current_stage).toLowerCase().includes(q));$('#projects').innerHTML=xs.length?xs.map(p=>`<div class="project-row" data-id="${p.id}"><div class="project-name"><b>${esc(p.name)}</b><small>${esc(p.description||'DCV 위임 가능 영역 연구')}</small></div><div><span class="stage-chip">${esc(p.current_stage)}</span></div><div class="mini-value">후보 ${num(p.candidate_count)}</div><div class="mini-value">승인 ${num(p.approval_count)}</div><button class="btn-ghost">열기 <i class="bi bi-chevron-right"></i></button></div>`).join(''):'<div class="p-4 text-secondary">검색 결과가 없습니다.</div>';document.querySelectorAll('.project-row').forEach(x=>x.onclick=()=>openProject(x.dataset.id,true));}
function renderEmpty(){document.body.classList.add('no-project');candidates=[];currentGateSnapshot=null;drawRegion([]);$('#evidenceMetrics').innerHTML='<div class="evidence-item evidence-empty"><span>RESEARCH DATA</span><b>대기</b><em>기존 프로젝트가 있다면 저장소 연결을 먼저 확인하세요.</em></div>';$('#regretPanel').innerHTML='<div class="regret-note"><b>Robust Minimax Regret</b><br>현재 프로젝트가 확인되면 실제 계산값을 표시합니다.<br><br><b>Human Recompute</b><br>기존 연구가 보이지 않는 상태에서는 새 연구 생성보다 저장소 복구가 우선입니다.</div>';$('#approvalPanel').innerHTML='<div class="approval-state"><div class="approval-ring" style="--progress:0%"><b>—</b></div><p>현재 프로젝트 데이터가 확인되면 승인 단계가 표시됩니다.</p></div>';}
async function openProject(id,focus,opts={}){current=id;localStorage.setItem('dcv_current_project',id);document.body.classList.remove('no-project');$('#detailPanel').classList.remove('d-none');const keep=opts.skipCandidates&&candidates.length;const [d,c]=await Promise.all([api(`/api/projects/${id}`),keep?null:api(`/api/projects/${id}/candidates`)]);if(c)candidates=c.candidates||[];currentResearchCycle=Number(d.project?.research_cycle||1);workflow(d.project.current_stage);$('#detailTitle').textContent=d.project.name;$('#detailSub').textContent=`${d.project.current_stage.toUpperCase()} · ${num(d.runs?.total)} simulation batches`;renderDetail(d);updateParticipantSessionUI(d);renderResearchBrief(d);window.dispatchEvent(new CustomEvent('dcv:project-loaded',{detail:{id,cycle:currentResearchCycle,revision:Number(d.project?.evidence_revision||0)}}));drawRegion(candidates);installDashboardHeightObserver();syncDashboardHeights();requestAnimationFrame(()=>{drawRegion(candidates);syncDashboardHeights();});document.querySelectorAll('.project-row').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));if(focus)focusDetail(d.project.name);return d;}

let _layoutSyncRaf=0,_layoutObserver=null;
function _clearSyncedHeights(){
  for(const el of [
    document.querySelector('#computeSection>.col-12:first-child>article'),
    document.getElementById('validateSection'),
    document.getElementById('recomputeSection'),
    document.querySelector('#projectsSection>.col-12:first-child>article'),
    document.querySelector('#approvalSection>article')
  ]) if(el){el.style.removeProperty('height');el.style.removeProperty('overflow');}
}
function syncDashboardHeights(){
  cancelAnimationFrame(_layoutSyncRaf);
  _layoutSyncRaf=requestAnimationFrame(()=>{
    if(window.innerWidth<1200){_clearSyncedHeights();drawRegion(candidates);return;}
    const left=document.querySelector('#computeSection>.col-12:first-child>article');
    const mid=document.getElementById('validateSection');
    const right=document.getElementById('recomputeSection');
    const matchReference=(reference,followers)=>{
      if(!reference)return;
      // Measure the natural border box, including padding and both borders.
      // Keep the reference unconstrained to avoid resize feedback loops.
      reference.style.removeProperty('height');
      const target=reference.getBoundingClientRect().height;
      if(target>0)for(const el of followers.filter(Boolean)){
        el.style.setProperty('height',target+'px','important');
        el.style.setProperty('overflow','auto','important');
      }
    };
    matchReference(right,[left,mid]);
    matchReference(document.querySelector('#approvalSection>article'),[
      document.querySelector('#projectsSection>.col-12:first-child>article')
    ]);
    drawRegion(candidates);
  });
}
function installDashboardHeightObserver(){
  if(_layoutObserver)return;
  if(!('ResizeObserver' in window))return;
  _layoutObserver=new ResizeObserver(()=>syncDashboardHeights());
  for(const el of [document.getElementById('recomputeSection'),document.querySelector('#approvalSection>article')]){
    if(el)_layoutObserver.observe(el);
  }
  document.fonts?.ready.then(syncDashboardHeights);
}
window.addEventListener('resize',syncDashboardHeights,{passive:true});

function jobExecutorBadge(type){
  const t=String(type||'');
  if(['measure_project','seed_candidates'].includes(t))return '<span class="exec-badge worker">WORKER FAST</span>';
  if(['advance_project','recompute_project','finalize_recompute','approve_project'].includes(t))return '<span class="exec-badge shared">SHARED FAST</span>';
  return '<span class="exec-badge github">GITHUB HEAVY</span>';
}
function renderDetail(d){const c=d.candidates||{},rm=d.reviewer?.model||{},approval=d.approval,emp=d.empirical||{};const conf=Number(c.feasible||0),unres=Number(c.unresolved||0),inf=Number(c.infeasible||0),total=Number(c.total||0);$('#regionBadge').className=`status-pill ${conf?'ok':unres?'hold':'neutral'}`;$('#regionBadge').textContent=conf?`${conf} CONFIRMED`:unres?`${unres} BOUNDARY`:'SEARCHING';const empLabel=emp.status==='FULL_EPISODE_PANEL'?'FULL 81':emp.status==='PARTIAL_EPISODE_PANEL'?`${num(emp.complete_rows)}/81`:'PAPER';$('#evidenceMetrics').innerHTML=`<div class="evidence-item"><span>CONFIRMED</span><b>${conf}</b><em>강건 후보</em></div><div class="evidence-item"><span>UNRESOLVED</span><b>${unres}</b><em>경계 표본 집중</em></div><div class="evidence-item"><span>INFEASIBLE</span><b>${inf}</b><em>제약 위반</em></div><div><small>UNEVALUATED</small><b>${num(c.unevaluated||0)}</b><em>연산 대기 · 판정 전</em></div><div class="evidence-item"><span>EMPIRICAL</span><b>${empLabel}</b><em>${esc(emp.status||'anchor pending')}</em></div><div class="evidence-item"><span>HUMAN N</span><b>${num(d.human_participants)}</b><em>누적 참가자 · 현재 분석 ${num(d.human_eligible_participants)}명</em></div>`;const regret=c.min_regret==null?NaN:Number(c.min_regret),rmeta=c.regret_meta||{};const cur=stageIdx(d.project.current_stage),ag=d.approval_gates||{gates:[],passed:0,total:6};currentGateSnapshot=ag;const g4=(ag.gates||[]).find(g=>g.id==='G4')?.status||'WAIT',g5=(ag.gates||[]).find(g=>g.id==='G5')?.status||'WAIT';$('#regretPanel').innerHTML=`<div class="regret-section"><div class="regret-section-head"><div><b>Robust Minimax Regret</b><small>Historical + Stress (Adversarial + BIS + ECB)</small></div><span class="status-pill ${Number.isFinite(regret)?'ok':'neutral'}">${Number.isFinite(regret)?'COMPUTED':'WAIT'}</span></div><div class="regret-score"><b>${Number.isFinite(regret)?regret.toFixed(4):'—'}</b><span>minimum max regret · normalized objective units</span></div><div class="regret-meta-grid"><div><span>Basis</span><b>${esc(rmeta.basis||'Historical + Stress')}</b></div><div><span>Snapshot</span><b>Cycle ${num(ag.research_cycle||d.project.research_cycle||1)} · Evidence r${num(ag.evidence_revision||d.project.evidence_revision||0)}</b></div><div><span>Scenarios used</span><b>${num(rmeta.scenario_count||0)} <small>H ${num(rmeta.historical_scenarios||0)} · A ${num(rmeta.adversarial_scenarios||0)} · BIS ${num(rmeta.bis_scenarios||0)} · ECB ${num(rmeta.ecb_scenarios||0)}</small></b></div><div><span>Last regret update</span><b>${esc(fmtTs(rmeta.last_updated_at))}</b></div></div><div class="regret-rule"></div><div class="regret-note"><b>Safety first, regret second.</b> 먼저 제약을 통과한 강건 후보만 비교합니다.<br><b>Human Recompute는 이 regret 지표에 포함되지 않습니다.</b> 인간실험만 추가된 경우 이 값이 그대로인 것이 정상입니다.</div></div><div class="human-recompute-box"><div class="regret-section-head"><div><b>Human Recompute</b><small>인간 검토행동 반영 후 후보 재판정 · 별도 G4→G5 경로</small></div><span class="status-pill ${g5==='PASS'?'ok':g4==='PASS'?'hold':'neutral'}">${g5==='PASS'?'G5 PASS':g4==='PASS'?'G4 PASS · G5 WAIT':'G4 WAIT'}</span></div><div class="human-recompute-grid"><div><span>Human observations</span><b>${num(d.human_reviews||0)}</b></div><div><span>Reviewer model</span><b>${g4==='PASS'?'READY':'WAIT'}</b></div><div><span>Recompute</span><b>${g5==='PASS'?'CONFIRMED':'WAIT'}</b></div>${rm.appropriate_reliance_rate!=null?`<div><span>ARR</span><b>${Number(rm.appropriate_reliance_rate).toFixed(3)}</b></div><div><span>Correct override</span><b>${Number(rm.correct_override_rate||0).toFixed(3)}</b></div>`:''}</div><div class="regret-note mt-2">G5까지 완료되면 후보 검증의 인간 보정 단계가 완료됩니다. G6 Scientific Sign-off는 통계 계산이 아니라 사람의 최종 학술 승인입니다.</div></div>`;const stale=!!d.project.approval_stale;const gateHtml=(ag.gates||[]).map(g=>`<div class="approval-gate"><span class="gate-id">${esc(g.id)}</span><div><b>${esc(g.name)}</b><small>${g.status==='PASS'?(g.id==='G6'?'학술 승인 완료':'게이트 완료'):(g.id==='G6'?'사람의 최종 승인 대기':'증거 대기/재검증')}</small></div><span class="${g.status==='PASS'?'gate-pass':'gate-wait'}">${g.status}</span></div>`).join('');$('#approvalPanel').innerHTML=`<div class="approval-state"><div class="approval-ring" style="--progress:${Math.min(100,(ag.passed||0)/(ag.total||6)*100)}%"><b>${ag.passed||0} / ${ag.total||6}</b></div><span class="status-pill ${approval?'ok':stale?'hold':'neutral'}">${approval?esc(approval.decision):stale?'EVIDENCE UPDATED':'IN PROGRESS'}</span><p>Cycle ${num(ag.research_cycle||d.project.research_cycle||1)} · Evidence r${num(ag.evidence_revision||d.project.evidence_revision||0)}${ag.revalidation_from?` · ${esc(ag.revalidation_from.toUpperCase())}부터 재검증`:''}</p>${stale?`<div class="approval-stale">새 증거가 추가되어 이전 승인은 STALE 처리되었습니다. 영향받는 단계부터 재검증 후 재승인이 필요합니다.</div>`:''}<div class="approval-gates">${gateHtml}</div></div>`;$('#pipeline').innerHTML=stageOrder.map((s,i)=>`<div class="detail-stage ${i<=cur?'active':''}">${s.toUpperCase()}</div>`).join('');$('#jobs').innerHTML=(d.jobs||[]).slice(0,10).map(j=>`<div class="job"><b>${esc(j.type)}</b> ${jobExecutorBadge(j.type)} · ${esc(j.status)} · ${j.attempts}회${j.last_error?`<br><span class="text-danger">${esc(j.last_error)}</span>`:''}</div>`).join('')||'<div class="job">작업 없음</div>';if($('#empiricalStatus'))$('#empiricalStatus').innerHTML=`<b>${esc(emp.status||'PUBLISHED_SUMMARY_ANCHOR')}</b> · episode ${num(emp.complete_rows)}/${num(emp.target_rows||81)} · profile ${esc(emp.profile?.version||'CBDC_PAPER_n81_2026')}${emp.local_refit?` · local refit n=${num(emp.local_refit.n)}`:''}${d.protocol?.protocol_hash?` · protocol <code>${esc(d.protocol.protocol_hash.slice(0,12))}…</code>`:''}`;const sb=$('#scientificSignoffBtn');if(sb){const ready=approval?.decision==='COMPUTATIONALLY_CONFIRMED';sb.classList.toggle('d-none',!ready);}}
function drawRegion(rows){const canvas=$('#regionCanvas'),rect=canvas.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const W=rect.width,H=rect.height,p={l:55,r:32,t:26,b:48},cw=W-p.l-p.r,ch=H-p.t-p.b;ctx.clearRect(0,0,W,H);ctx.fillStyle='#f8fbfe';ctx.fillRect(p.l,p.t,cw,ch);ctx.strokeStyle='#dce7f1';ctx.lineWidth=1;ctx.font='11px system-ui';ctx.fillStyle='#6f8297';for(let i=0;i<=5;i++){let x=p.l+cw*i/5,y=p.t+ch*i/5;ctx.beginPath();ctx.moveTo(x,p.t);ctx.lineTo(x,p.t+ch);ctx.stroke();ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(p.l+cw,y);ctx.stroke();ctx.fillText((i/5).toFixed(1),x-8,p.t+ch+20);ctx.fillText((1-i/5).toFixed(1),18,y+4);}ctx.fillStyle='#566f89';ctx.fillText('σ  정보오차 →',p.l+cw/2-35,H-9);ctx.save();ctx.translate(13,p.t+ch/2+35);ctx.rotate(-Math.PI/2);ctx.fillText('α  정보처리 강도 →',0,0);ctx.restore();if(!rows.length){ctx.fillStyle='#708296';ctx.font='14px system-ui';ctx.fillText('후보 데이터가 생성되면 위임 가능 영역이 표시됩니다.',p.l+30,p.t+ch/2);return;}const sig=rows.map(x=>Number(x.sigma)),alp=rows.map(x=>Number(x.alpha)),smin=Math.min(...sig),smax=Math.max(...sig),amin=Math.min(...alp),amax=Math.max(...alp);const nx=v=>(v-smin)/(Math.max(.001,smax-smin)),ny=v=>(v-amin)/(Math.max(.001,amax-amin));for(const r of rows){const x=p.l+nx(Number(r.sigma))*cw,y=p.t+(1-ny(Number(r.alpha)))*ch;let color='#ff6685',size=3.2,glow=0;if(r.status==='confirmed_feasible'||r.final_status==='CONFIRM'){color='#20d2b5';size=5;glow=10}else if(r.evidence_status==='UNRESOLVED'||r.status==='boundary_hold'||r.status==='unresolved'){color='#ffc857';size=4.2;glow=9}else if(r.status==='provisionally_feasible'){color='#27e0ff';size=4;glow=8}ctx.save();ctx.shadowColor=color;ctx.shadowBlur=glow;ctx.fillStyle=color;ctx.globalAlpha=.84;ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill();ctx.restore();}const feasible=rows.filter(r=>r.status==='confirmed_feasible'||r.final_status==='CONFIRM').sort((a,b)=>Number(a.sigma)-Number(b.sigma));if(feasible.length>2){ctx.strokeStyle='rgba(39,224,255,.65)';ctx.setLineDash([6,5]);ctx.lineWidth=1.5;ctx.beginPath();feasible.forEach((r,i)=>{const x=p.l+nx(Number(r.sigma))*cw,y=p.t+(1-ny(Number(r.alpha)))*ch;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.setLineDash([]);}}
