$('#trialBtn').onclick=()=>startTrial();async function startTrial(){if(!current)return;const ph=ensureParticipantSession();try{const t=await api(`/api/projects/${current}/reviewer-trials`,{method:'POST',body:JSON.stringify({participant_hash:ph})}),started=performance.now();$('#trial').innerHTML=`<div class="trial-card"><b>통제된 지급결제 판단 실험 · ${t.trial_number}/${t.cap}</b><p>지급금액 ${t.task.amount}, 승인 한도 ${t.task.limit}. 금액이 한도를 초과한 경우에만 지급을 정지해야 합니다.</p><p>AI 권고: <b>${t.recommendation?'지급 정지':'지급 허용'}</b> · 설계 신뢰도 ${(t.confidence*100).toFixed(0)}%</p><small>정답률은 실험에서 부여한 확률이며 실제 AI 성능이 아닙니다.</small><div class="trial-actions"><button class="btn-future" id="accept">권고 수용</button><button class="btn-ghost" id="override">인간 개입</button></div></div>`;let sent=false;const send=async accept=>{if(sent)return;sent=true;try{const rr=await api(`/api/projects/${current}/reviewer-observations`,{method:'POST',body:JSON.stringify({trial_id:t.trial_id,participant_hash:ph,human_accept:accept,response_ms:Math.round(performance.now()-started)})});$('#trial').innerHTML=`<div class="trial-card">기록 완료 · AI 권고는 <b>${rr.correct?'정답':'오답'}</b>이었습니다. · Evidence r${rr.revalidation.evidence_revision}</div>`;await openProject(current,false,{skipCandidates:true});}catch(e){sent=false;toast(e.message,true);}};$('#accept').onclick=()=>send(true);$('#override').onclick=()=>send(false);}catch(e){$('#trial').textContent=e.message==='participant_trial_cap_reached'?'이번 연구 주기의 참가자별 30회 상한에 도달했습니다.':e.message;}}
