(function(){const oc=document.getElementById('dcvMenu');if(!oc)return;
const links=[...oc.querySelectorAll('[data-menu-target]')];
const setActive=a=>links.forEach(x=>x.classList.toggle('active',x===a));
function flash(el){el.animate([{boxShadow:'0 0 0 2px rgba(39,224,255,.9)'},{boxShadow:'0 0 0 0 rgba(39,224,255,0)'}],{duration:1400});}
async function go(id){
 const need=['dataSection','empiricalSection'].includes(id);
 if(need&&!current){if(projects[0])await openProject(projects[0].id);else{id='projectsSection';alert('먼저 연구 프로젝트를 생성하세요.');}}
 if(id==='reportSection'){if(current){showReport(false);return}id='projectsSection';alert('먼저 연구 프로젝트를 선택하세요.');}
 const el=document.getElementById(id==='dashboard'?'dashboard':id);if(!el)return;
 if(id==='dashboard')window.scrollTo({top:0,behavior:'smooth'});else{el.scrollIntoView({behavior:'smooth',block:'start'});flash(el);}
 history.replaceState(null,'','#'+id);}
links.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setActive(a);const id=a.dataset.menuTarget;
 // offcanvas가 body 스크롤을 잠근 상태에서는 스크롤이 안 되므로 완전히 닫힌 뒤 이동
 oc.addEventListener('hidden.bs.offcanvas',()=>go(id),{once:true});
 bootstrap.Offcanvas.getOrCreateInstance(oc).hide();}));
})();
