let wbData=null;
const wbFmt=(v,d=4)=>v==null||!Number.isFinite(Number(v))?'-':Number(v).toFixed(d);
const wbJson=v=>{try{return JSON.stringify(v||{},null,2)}catch{return '{}'}};
function wbCard(title,value,sub='',tone='') {return `<div class="wb-metric ${tone}"><small>${esc(title)}</small><b>${value}</b>${sub?`<em>${esc(sub)}</em>`:''}</div>`;}
function wbRowsFinancial(xs=[]){if(!xs.length)return '<div class="wb-empty">FDIC Financials 원자료가 없습니다.</div>';return `<div class="table-responsive"><table class="table table-sm wb-table"><thead><tr><th>REPDTE</th><th>Assets</th><th>Total Deposits</th><th>Domestic Deposits</th><th>Uninsured</th><th>Equity</th></tr></thead><tbody>${xs.map(x=>`<tr><td>${esc(x.repdte)}</td><td>${wbFmt(x.asset,0)}</td><td>${wbFmt(x.deposits_total,0)}</td><td>${wbFmt(x.deposits_domestic,0)}</td><td>${wbFmt(x.uninsured_deposits,0)}</td><td>${wbFmt(x.equity,0)}</td></tr>`).join('')}</tbody></table></div>`;}
function wbRowsSod(xs=[]){if(!xs.length)return '<div class="wb-empty">FDIC SOD 원자료가 없습니다.</div>';return `<div class="table-responsive"><table class="table table-sm wb-table"><thead><tr><th>Year</th><th>Branch</th><th>State</th><th>County</th><th>City</th><th>Deposits</th></tr></thead><tbody>${xs.slice(0,80).map(x=>`<tr><td>${x.year??'-'}</td><td>${esc(x.branch_num||'-')}</td><td>${esc(x.state||'-')}</td><td>${esc(x.county||'-')}</td><td>${esc(x.cbsa||'-')}</td><td>${wbFmt(x.branch_deposits,0)}</td></tr>`).join('')}</tbody></table>${xs.length>80?`<small class="text-secondary">상위 80개 branch만 표시 · API 반환 ${xs.length}행</small>`:''}</div>`;}
function renderFdicWorkbench(d){wbData=d;const e=d.episode,r=d.ranking,l=d.link,m=d.market,fs=d.financials?.summary||{},rv=d.review||{};
  document.getElementById('wbSubtitle').textContent=`${e.name} · ${e.year} · CERT ${l.cert??'-'} · ${l.institution_name||'FDIC institution'}`;
  const pri=document.getElementById('wbPriority');pri.textContent=r.priority_level||'-';pri.className=`rank-pill ${String(r.priority_level||'').toLowerCase()} ms-3`;
  const causeOpts=(d.suggested_causes||[]).map(x=>`<option value="${esc(x.code)}" ${rv.cause_code===x.code?'selected':''}>${esc(x.label)} — ${esc(x.why)}</option>`).join('');
  const causeCodes=[...new Set((d.suggested_causes||[]).map(x=>x.code))];if(rv.cause_code&&!causeCodes.includes(rv.cause_code))causeOpts+=`<option value="${esc(rv.cause_code)}" selected>${esc(rv.cause_code)}</option>`;
  const checklist=(d.checklist||[]).map(x=>`<label class="wb-check"><input class="form-check-input wb-check-input" type="checkbox" data-check="${esc(x.id)}" ${rv.checklist?.[x.id]?'checked':''}><span>${esc(x.label)}</span></label>`).join('');
  const financeChart=(d.financials?.rows||[]).map(x=>({date:x.repdte,dep:Number(x.deposits_domestic??x.deposits_total)})).filter(x=>Number.isFinite(x.dep));
  const chartSvg=financeChart.length?`<svg viewBox="0 0 720 170" class="wb-spark"><polyline points="${financeChart.map((x,i)=>{const vals=financeChart.map(z=>z.dep),mn=Math.min(...vals),mx=Math.max(...vals),px=25+i*(670/Math.max(1,financeChart.length-1)),py=145-(x.dep-mn)/(Math.max(1,mx-mn))*110;return `${px},${py}`}).join(' ')}" fill="none" stroke="currentColor" stroke-width="3"/><line x1="25" y1="145" x2="695" y2="145" stroke="currentColor" opacity=".25"/></svg>`:'<div class="wb-empty">예금 시계열 없음</div>';
  document.getElementById('wbBody').innerHTML=`
    <div class="wb-alert"><i class="bi bi-shield-exclamation"></i><div><b>재검증 원칙</b><span>이 Workbench는 discrepancy 원인을 확인하기 위한 감사·검증 도구입니다. FDIC 값은 기존 논문 값을 자동 대체하지 않으며, 최종 원인과 조치는 검토자가 기록합니다.</span></div></div>
    <div class="wb-grid mt-3">
      <section class="wb-panel wb-span-2"><div class="wb-title"><span>01</span><div><b>원 논문 값 vs FDIC 검증값</b><small>Side-by-side evidence</small></div></div><div class="wb-metrics">
       ${wbCard('Panel concentration C',wbFmt(e.concentration,4),e.provenance_type)}${wbCard('FDIC state HHI',wbFmt(r.fdic_hhi,4),m.key?`state ${m.key}`:'state market')}${wbCard('|ΔC|',wbFmt(r.concentration_gap,4),`percentile ${wbFmt(r.concentration_percentile,3)}`,Number(r.concentration_percentile)>=.8?'danger':'')}
       ${wbCard('Panel peak_outflow',wbFmt(e.peak_outflow,4),'thesis panel')}${wbCard('FDIC peak drawdown',wbFmt(r.fdic_peak_drawdown,4),r.peak_drawdown_date||'quarterly proxy')}${wbCard('|ΔDeposit|',wbFmt(r.deposit_gap,4),`percentile ${wbFmt(r.deposit_percentile,3)}`,Number(r.deposit_percentile)>=.8?'danger':'')}
      </div></section>
      <section class="wb-panel"><div class="wb-title"><span>02</span><div><b>FDIC Linkage</b><small>CERT & market definition</small></div></div><dl class="wb-dl"><dt>CERT</dt><dd>${l.cert??'-'}</dd><dt>기관명</dt><dd>${esc(l.institution_name||'-')}</dd><dt>Match</dt><dd>${esc(l.match_method||'-')} · ${wbFmt(l.match_score,3)}</dd><dt>시장</dt><dd>${esc(m.type||'-')} / ${esc(m.key||'-')}</dd><dt>은행 수</dt><dd>${m.bank_count??'-'}</dd><dt>Target share</dt><dd>${wbFmt(m.target_bank_share,4)}</dd></dl></section>
      <section class="wb-panel"><div class="wb-title"><span>03</span><div><b>차이 원인 후보</b><small>자동 제안 · 검토자 확정 필요</small></div></div><div class="wb-cause-list">${(d.suggested_causes||[]).map(x=>`<div><b>${esc(x.label)}</b><span>${esc(x.why)}</span></div>`).join('')}</div></section>
      <section class="wb-panel wb-span-2"><div class="wb-title"><span>04</span><div><b>Deposit Dynamics</b><small>FDIC Financials · quarterly observations</small></div></div>${chartSvg}<div class="wb-inline-stats"><span>points <b>${fs.deposit_points??0}</b></span><span>first <b>${esc(fs.first?.repdte||'-')}</b></span><span>last <b>${esc(fs.last?.repdte||'-')}</b></span><span>peak DD <b>${wbFmt(fs.peak_drawdown,4)}</b></span></div>${wbRowsFinancial(d.financials?.rows||[])}</section>
      <section class="wb-panel wb-span-2"><div class="wb-title"><span>05</span><div><b>Summary of Deposits Raw</b><small>FDIC SOD · target institution branches</small></div></div>${wbRowsSod(d.sod?.rows||[])}</section>
      <section class="wb-panel"><div class="wb-title"><span>06</span><div><b>재검증 체크리스트</b><small>${(d.checklist||[]).length} required checks</small></div></div><div class="wb-checks">${checklist}</div></section>
      <section class="wb-panel"><div class="wb-title"><span>07</span><div><b>검토 결론</b><small>Human scientific judgment</small></div></div>
        <label class="form-label">상태</label><select id="wbReviewStatus" class="form-select"><option ${rv.review_status==='OPEN'?'selected':''}>OPEN</option><option ${rv.review_status==='IN_REVIEW'?'selected':''}>IN_REVIEW</option><option ${rv.review_status==='ESCALATED'?'selected':''}>ESCALATED</option><option ${rv.review_status==='RESOLVED'?'selected':''}>RESOLVED</option></select>
        <label class="form-label">주된 원인</label><select id="wbCause" class="form-select"><option value="">선택</option>${causeOpts}</select>
        <label class="form-label">권고 조치</label><select id="wbAction" class="form-select"><option value="NO_CHANGE" ${rv.recommended_action==='NO_CHANGE'?'selected':''}>NO_CHANGE</option><option value="KEEP_PANEL" ${rv.recommended_action==='KEEP_PANEL'?'selected':''}>KEEP_PANEL</option><option value="UPDATE_PROVENANCE" ${rv.recommended_action==='UPDATE_PROVENANCE'?'selected':''}>UPDATE_PROVENANCE</option><option value="REPLACE_CANDIDATE" ${rv.recommended_action==='REPLACE_CANDIDATE'?'selected':''}>REPLACE_CANDIDATE</option><option value="NEED_PRIMARY_SOURCE" ${rv.recommended_action==='NEED_PRIMARY_SOURCE'?'selected':''}>NEED_PRIMARY_SOURCE</option><option value="NEED_METHOD_REVIEW" ${rv.recommended_action==='NEED_METHOD_REVIEW'?'selected':''}>NEED_METHOD_REVIEW</option></select>
        <label class="form-label">검토자</label><input id="wbReviewer" class="form-control" value="${esc(rv.reviewer_name||'')}" placeholder="이름 또는 역할">
        <label class="form-label">원인 메모</label><textarea id="wbCauseNote" class="form-control" rows="2" placeholder="차이 발생 원인을 기술">${esc(rv.cause_note||'')}</textarea>
        <label class="form-label">최종 검토 메모</label><textarea id="wbReviewerNote" class="form-control" rows="4" placeholder="primary source 확인 내용, 유지/수정 근거 등">${esc(rv.reviewer_note||'')}</textarea>
        ${rv.evidence_revision?`<div class="wb-evidence">Evidence revision <b>r${rv.evidence_revision}</b>에 반영됨</div>`:''}
      </section>
    </div>`;
  document.getElementById('wbLoading').classList.add('d-none');document.getElementById('wbBody').classList.remove('d-none');document.getElementById('wbSaveState').textContent=`현재 상태: ${rv.review_status||'OPEN'}`;
}
async function openFdicWorkbench(episodeId){if(!current||!episodeId)return;document.getElementById('wbBody').classList.add('d-none');document.getElementById('wbLoading').classList.remove('d-none');document.getElementById('wbSaveState').textContent='불러오는 중…';modal('fdicWorkbenchModal').show();try{const d=await api(`/api/projects/${current}/fdic/workbench/${encodeURIComponent(episodeId)}`);renderFdicWorkbench(d);}catch(e){document.getElementById('wbLoading').classList.add('d-none');document.getElementById('wbBody').classList.remove('d-none');document.getElementById('wbBody').innerHTML=`<div class="alert alert-danger">Workbench 로드 실패: ${esc(e.message)}</div>`;}}
if(document.getElementById('wbSaveBtn'))document.getElementById('wbSaveBtn').onclick=async()=>{if(!current||!wbData)return;const btn=document.getElementById('wbSaveBtn');btn.disabled=true;try{const checklist={};document.querySelectorAll('.wb-check-input').forEach(x=>checklist[x.dataset.check]=x.checked);const body={review_status:document.getElementById('wbReviewStatus').value,cause_code:document.getElementById('wbCause').value,cause_note:document.getElementById('wbCauseNote').value,reviewer_name:document.getElementById('wbReviewer').value,reviewer_note:document.getElementById('wbReviewerNote').value,recommended_action:document.getElementById('wbAction').value,checklist};const r=await api(`/api/projects/${current}/fdic/workbench/${encodeURIComponent(wbData.episode.id)}`,{method:'POST',body:JSON.stringify(body)});document.getElementById('wbSaveState').textContent=`저장됨 · ${r.review_status}${r.revalidation?` · Evidence r${r.revalidation.evidence_revision}`:''}`;toast(r.review_status==='RESOLVED'?'재검증 완료 · 증거 revision에 반영되었습니다.':'Workbench 검토 내용이 저장되었습니다.');const fresh=await api(`/api/projects/${current}/fdic/workbench/${encodeURIComponent(wbData.episode.id)}`);renderFdicWorkbench(fresh);await loadFdicStatus();if(r.revalidation)await openProject(current,false,{skipCandidates:true});}catch(e){alert(`검토 저장 실패: ${e.message}`)}finally{btn.disabled=false}};

/* ── Official multi-source data layers: BIS CPMI → ECB → ECOS / Case B ── */
async function loadOfficialStatus(){
  if(!current||!document.getElementById('officialStatus'))return;
  try{
    const r=await api(`/api/projects/${current}/official-sources/status`),src=r.sources||[],layers=r.layers||[],maps=r.mappings||[];
    const ready=src.filter(x=>x.last_status==='ok').length,errs=src.filter(x=>String(x.last_status||'').startsWith('error')).length;
    document.getElementById('officialBadge').className=`status-pill ${errs?'warn':ready?'good':'neutral'}`;
    document.getElementById('officialBadge').textContent=errs?`${errs} ERROR`:ready?`${ready}/${src.length} SYNCED`:src.length?`${src.length} CONFIGURED`:'NOT CONFIGURED';
    const mlines=maps.map(x=>{const p=x.payload||{},c=x.components||{};if(x.mapping_key==='D_CPMI')return `MAP D_CPMI · ${x.method_version} · ${x.period||'-'} · D*=${Number(x.value_num).toFixed(3)} · level=${Number(c.historical_level_percentile??NaN).toFixed(3)} · fast-share=${Number(c.fast_payment_share??NaN).toFixed(3)}`;if(x.mapping_key==='R_ECB')return `MAP R_ECB · ${x.method_version} · ${x.period||'-'} · R=${Number(x.value_num).toFixed(3)} · θ*=${Number(p.theta_external??NaN).toFixed(3)} · LCR=${Number(c.lcr_pct??NaN).toFixed(1)} · CET1=${Number(c.cet1_pct??NaN).toFixed(1)}`;return `MAP ${x.mapping_key} · ${x.value_num}`;});
    document.getElementById('officialStatus').textContent=[...layers.map(x=>`${x.layer_code} · ${x.case_name} · ${x.status}`),...src.map(x=>`${x.case_layer}/${x.connector_id} · ${x.data_role||'-'} · ${x.last_status||'not fetched'} · rows ${x.coverage?.rows||0} · ${x.coverage?.first_period||'-'}~${x.coverage?.last_period||'-'}`),...mlines].join('\n')||'공식 데이터 계층이 없습니다.';
  }catch(e){document.getElementById('officialStatus').textContent=`공식 데이터 상태 조회 실패: ${e.message}`;}
}
function matrixClass(code){return code==='PASS'?'matrix-pass':code==='FAIL'?'matrix-fail':code==='HOLD'?'matrix-hold':code==='PARTIAL'?'matrix-partial':'matrix-missing';}
async function loadExternalMatrix(){
  const sum=document.getElementById('externalMatrixSummary'),box=document.getElementById('externalMatrixTable'),badge=document.getElementById('externalMatrixBadge');
  if(!current||!sum||!box||!badge)return;
  try{
    const vm=await api(`/api/projects/${current}/validation-matrix`),rows=vm.rows||[],dims=vm.dimensions||[];
    if(!rows.length){const g3=(currentGateSnapshot?.gates||[]).find(g=>g.id==='G3')?.status||'WAIT',g5=(currentGateSnapshot?.gates||[]).find(g=>g.id==='G5')?.status||'WAIT';badge.className='status-pill neutral';badge.textContent='NO DATA';sum.innerHTML=`<small class="text-secondary"><b>현재 Evidence r${vm.current_revision??vm.revision??'-'} 기준:</b> ${g3==='PASS'?'G3 Robust Validation은 완료되었으나 Matrix snapshot 생성/동기화를 기다리는 중입니다.':'G3 Robust Validation 완료 후 Matrix/Funnel이 생성됩니다.'} ${g5==='PASS'?'Human 열까지 확정됩니다.':'G5 Recompute 완료 시 Human 열까지 확정됩니다.'}</small>`;box.innerHTML='';const funnel=document.getElementById('externalFunnel'),fm=document.getElementById('externalFunnelMeta');if(fm)fm.textContent=`${vm.project_name||'현재 프로젝트'} · Cycle ${vm.current_cycle??vm.cycle??'-'} · Evidence r${vm.current_revision??vm.revision??'-'} · G3 후 생성 / G5 후 Human 확정`;if(funnel)funnel.innerHTML=`<small class="text-secondary">${g3==='PASS'?'현재 snapshot 동기화 대기':'G3 Robust Validation 대기'} · G5 완료 전 Human은 N/A일 수 있습니다.</small>`;return;}
    if(vm.stale){badge.className='status-pill warn';badge.textContent=`STALE r${vm.revision} → r${vm.current_revision}`;}
    const sd=vm.summary?.dimensions||{};
    if(!vm.stale){badge.className=`status-pill ${vm.summary?.FAIL?'warn':vm.summary?.PASS?'good':'neutral'}`;badge.textContent=`${rows.length} CANDIDATES`;}
    const staleBanner=vm.stale?`<div class="matrix-stale-banner"><b>재검증 진행 중</b> · 현재 Evidence r${vm.current_revision} / 표시 snapshot r${vm.revision}. 직전 유효 Matrix를 보존 표시하며 최신 검증 완료 후 자동 교체됩니다.</div>`:'';
    sum.innerHTML=staleBanner+dims.map(k=>{const x=sd[k]||{},obs=(x.PASS||0)+(x.HOLD||0)+(x.FAIL||0);return `<div class="ext-matrix-chip"><span>${esc(k)}</span><b>${num(x.PASS||0)}/${num(obs)}</b><small>H ${num(x.HOLD||0)} · F ${num(x.FAIL||0)} · N/A ${num(x.NA||0)}</small></div>`;}).join('')+`<div class="ext-matrix-chip"><span>Overall</span><b>${num(vm.summary?.PASS||0)} PASS</b><small>${num(vm.summary?.PARTIAL||0)} partial · ${num(vm.summary?.HOLD||0)} hold · ${num(vm.summary?.FAIL||0)} fail</small></div>`;
    const headers=['Candidate',...dims,'Overall'];
    box.innerHTML=`<table class="matrix-table"><thead><tr>${headers.map((h,i)=>`<th${i===0?' style="min-width:225px"':''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><div class="${r.overall_status==='PASS'?'matrix-overall-pass':r.overall_status==='FAIL'?'matrix-overall-fail':r.overall_status==='HOLD'?'matrix-overall-hold':''}"><b>${esc(String(r.estimator||'').toUpperCase())}</b> σ=${num(r.sigma,3)} α=${num(r.alpha,3)} K=${num(r.authority_k)} d=${num(r.delay_d,2)}</div></td>${dims.map(k=>{const code=r[`${k.toLowerCase()}_status`]||'NA';return `<td><span class="matrix-cell ${matrixClass(code)}">${esc(code)}</span></td>`}).join('')}<td><span class="matrix-cell ${matrixClass(r.overall_status)}">${esc(r.overall_status||'NA')}</span></td></tr>`).join('')}</tbody></table>`;
    const funnel=document.getElementById('externalFunnel'),fm=document.getElementById('externalFunnelMeta');if(fm)fm.textContent=vm.stale?`${vm.project_name||'현재 프로젝트'} · 표시 snapshot Cycle ${vm.cycle} / Evidence r${vm.revision} · 현재 r${vm.current_revision} 재검증 중 · ${rows.length}개 후보 · ${vm.snapshot_updated_at||''}`:`${vm.project_name||'현재 프로젝트'} · Cycle ${vm.cycle??'-'} · Evidence r${vm.revision??'-'} · ${rows.length}개 현재 후보에서 계산 · 예시값 없음 · ${vm.generated_at||''}`;if(funnel){const order=['Synthetic','Historical','Adversarial','BIS','ECB','Human'];let pool=[...rows];const steps=[{stage:'Candidate pool',survivors:pool.length,unavailable:false}];for(const k of order){const field=`${k.toLowerCase()}_status`,observed=rows.filter(r=>(r[field]||'NA')!=='NA').length;if(!observed){steps.push({stage:k,survivors:pool.length,unavailable:true});continue;}pool=pool.filter(r=>(r[field]||'NA')==='PASS');steps.push({stage:k,survivors:pool.length,unavailable:false});}const initial=Math.max(1,rows.length);funnel.innerHTML=steps.map((x,i)=>`<div class="funnel-step ${x.unavailable?'funnel-na':''}" style="width:${Math.max(28,100*Math.sqrt(x.survivors/initial))}%"><span>${esc(x.stage)}</span><b>${num(x.survivors)}</b><small>${x.unavailable?'N/A':`${Math.round(100*x.survivors/initial)}%`}</small></div>`).join('');}
  }catch(e){badge.className='status-pill warn';badge.textContent='ERROR';sum.innerHTML=`<small class="text-danger">External Validation Matrix 로드 실패: ${esc(e.message)}</small>`;box.innerHTML='';const funnel=document.getElementById('externalFunnel');if(funnel)funnel.innerHTML='';}
}
const _dcvOpenProjectCore=openProject;
const auxSnapshotCache=new Map(),auxSnapshotPending=new Map();
function scheduleProjectAux(d,force=false){
  if(!d?.project)return;
  const id=d.project.id,cycle=Number(d.project.research_cycle||1),rev=Number(d.project.evidence_revision||0);
  const key=`${id}|${cycle}|${rev}`;
  if(!force&&auxSnapshotCache.get(id)===key)return;
  if(!force&&auxSnapshotPending.get(id)===key)return;
  auxSnapshotPending.set(id,key);
  const loadAux=async()=>{
    const results=await Promise.allSettled([loadFdicStatus(),loadOfficialStatus(),loadExternalMatrix()]);
    auxSnapshotPending.delete(id);
    if(results.every(x=>x.status==='fulfilled')) auxSnapshotCache.set(id,key);
    else {auxSnapshotCache.delete(id);setTimeout(()=>{if(current===id)scheduleProjectAux(d,true);},700);}
    syncDashboardHeights();
  };
  if('requestIdleCallback' in window)requestIdleCallback(loadAux,{timeout:250});
  else setTimeout(loadAux,0);
}
openProject=async function(id,focus,opts={}){
  const d=await _dcvOpenProjectCore(id,focus,opts);
  scheduleProjectAux(d,!!opts.refreshAux);
  return d;
};
