/* v0.5.19 bootstrap: run only after every project wrapper / auxiliary loader is registered. */
let _dcvBooted=false;
async function bootstrapDCV(){
  if(_dcvBooted)return;
  _dcvBooted=true;
  workflow();
  void loadSourcePresets();
  for(let attempt=0;attempt<3;attempt++){
    const ok=await load();
    if(ok)return;
    await new Promise(r=>setTimeout(r,[250,650,1200][attempt]||1200));
  }
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootstrapDCV,{once:true});else bootstrapDCV();
